import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String name = sc.nextLine().trim();
        int start = Integer.parseInt(sc.nextLine().trim());
        int completed = Integer.parseInt(sc.nextLine().trim());
        int end = start + completed;
        int remaining = 30 - end;
        System.out.println("Student: " + name);
        System.out.println("Plan: Day " + start + " to Day " + end);
        System.out.println("Days completed: " + completed);
        System.out.println("Days remaining: " + remaining);
    }
}

import java.util.Scanner;

